import app from 'flarum/common/app';

/** What a chapter's discussion page carries (the `anthologySeries` attribute). */

/** A tag in the directory's tag menu (Tags on). */

const url = path => app.forum.attribute('apiUrl') + path;
const person = user => user ? {
  id: Number(user.id()),
  username: user.username(),
  displayName: user.displayName(),
  avatarUrl: user.avatarUrl() || null,
  slug: user.slug()
} : null;
const card = s => ({
  id: Number(s.id()),
  slug: s.slug(),
  title: s.title(),
  excerpt: s.excerpt(),
  coverUrl: s.coverUrl(),
  status: s.status(),
  chapterCount: s.chapterCount(),
  followerCount: s.followerCount(),
  lastChapterAt: s.lastChapterAt(),
  author: person(s.user()),
  canEdit: s.canEdit(),
  description: s.description()
});
const full = s => ({
  ...card(s),
  description: s.description(),
  createdAt: s.createdAt(),
  chapters: s.chapters() || [],
  following: !!s.following(),
  canFollow: s.canFollow(),
  canDelete: s.canDelete()
});

// The directory's sort names and filters, as the series resource knows them.
const SORTS = {
  new: '-createdAt',
  popular: '-followerCount',
  title: 'title'
};

/** A series from the store, loaded first if this page hasn't seen it. */
const stored = id => {
  const model = app.store.getById('anthology-series', String(id));
  return model ? Promise.resolve(model) : app.store.find('anthology-series', String(id));
};

/**
 * `filter`: user, mine, tag, status, q (the start of a title); `published` keeps series with a chapter to open
 * (the directory). `sort`: latest (default), new, popular, title. `tags`: the tag menu comes too.
 */
export const listSeries = params => {
  const {
    q,
    ...filter
  } = params.filter || {};
  const offset = params.page?.offset || 0;
  const query = {
    filter: {
      ...filter,
      ...(q ? {
        title: q
      } : {}),
      ...(params.published ? {
        published: '1'
      } : {})
    },
    sort: SORTS[params.sort || ''] || '-lastChapterAt',
    page: {
      offset
    }
  };
  if (params.tags) query.withTags = 1;
  return app.store.find('anthology-series', query).then(list => ({
    data: list.map(card),
    meta: {
      next: list.payload.links?.next ? offset + list.length : null,
      tags: list.payload.meta?.tags || undefined
    }
  }));
};
export const showSeries = id => app.store.find('anthology-series', String(id)).then(s => ({
  data: full(s)
}));

/** `userId` (moderators): start it for that member, who is in the store with their discussion. */
export const saveSeries = (id, {
  userId,
  ...attributes
}) => {
  const owner = !id && userId ? app.store.getById('users', String(userId)) : undefined;
  const model = id ? stored(id) : Promise.resolve(app.store.createRecord('anthology-series'));
  return model.then(s => s.save({
    ...attributes,
    ...(owner ? {
      relationships: {
        user: owner
      }
    } : {})
  })).then(s => ({
    data: card(s)
  }));
};
export const deleteSeries = id => stored(id).then(s => s.delete());
export const uploadCover = (id, file) => {
  const body = new FormData();
  body.append('cover', file);
  return app.request({
    method: 'POST',
    url: url('/anthology-series/' + id + '/cover'),
    serialize: raw => raw,
    body
  });
};
export const removeCover = id => app.request({
  method: 'DELETE',
  url: url('/anthology-series/' + id + '/cover')
});
export const follow = (id, on) => stored(id).then(s => s.save({
  following: on
})).then(s => ({
  data: {
    following: !!s.following(),
    followerCount: s.followerCount()
  }
}));
export const reorder = (id, ids) => stored(id).then(s => s.save({
  chapterOrder: ids
}));

/** Files a discussion under a series (null takes it out); the answer is what its page shows. */
const fileChapter = (discussionId, seriesId) => {
  const known = app.store.getById('discussions', String(discussionId));
  return (known ? Promise.resolve(known) : app.store.find('discussions', String(discussionId))).then(d => d.save({
    anthologySeriesId: seriesId
  })).then(d => ({
    data: d.attribute('anthologySeries')
  }));
};
export const addChapter = (discussionId, seriesId) => fileChapter(discussionId, seriesId);
export const removeChapter = discussionId => fileChapter(discussionId, null);
flarum.reg.add('ernestdefoe-anthology', 'common/api', { listSeries: listSeries,showSeries: showSeries,saveSeries: saveSeries,deleteSeries: deleteSeries,uploadCover: uploadCover,removeCover: removeCover,follow: follow,reorder: reorder,addChapter: addChapter,removeChapter: removeChapter, });